import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.B0ak8Y9a.js";const k=JSON.parse('{"title":"OME-Zarr","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/feat-webknossos-axes/data/ome-zarr.html"}],["meta",{"property":"og:title","content":"OME-Zarr | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/feat-webknossos-axes/data/ome-zarr.html"}],["meta",{"name":"twitter:title","content":"OME-Zarr | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"data/ome-zarr.md","filePath":"data/ome-zarr.md"}'),r={name:"data/ome-zarr.md"};function o(n,e,l,d,h,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="ome-zarr" tabindex="-1">OME-Zarr <a class="header-anchor" href="#ome-zarr" aria-label="Permalink to &quot;OME-Zarr&quot;">​</a></h1><p>Kiln supports two input formats:</p><table tabindex="0"><thead><tr><th>Format</th><th>Preprocessing</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>OME-Zarr (NGFF v0.4/v0.5)</strong></td><td>None — no Kiln-specific conversion</td><td>Standard scientific imaging format, chunked arrays</td></tr><tr><td><strong>Kiln sharded binary</strong></td><td>Requires <a href="/preview/feat-webknossos-axes/data/sharded-binary.html">conversion script</a></td><td>Gzip-compressed bricks, HTTP Range streaming</td></tr></tbody></table><p>Kiln can load compatible multiscale <a href="https://ngff.openmicroscopy.org/" target="_blank" rel="noreferrer">OME-Zarr</a> volumes directly over HTTP, with no Kiln-specific conversion. Point it at a <code>.ome.zarr</code> URL and it streams chunk data on demand.</p><p>Kiln is listed in the <a href="https://ngff.openmicroscopy.org/resources/tools/index.html" target="_blank" rel="noreferrer">OME-NGFF tools registry</a>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><strong>OME-NGFF v0.4 and v0.5</strong> with <code>multiscales</code> metadata in group attributes</li><li><strong>Single-channel or multichannel</strong> — up to 4 channels (see <a href="/preview/feat-webknossos-axes/rendering/multichannel.html">Multichannel</a>)</li><li><strong>3D arrays</strong> with x, y and z as the last three dimensions, usually <code>[z, y, x]</code>; <code>[x, y, z]</code> as written by <a href="https://webknossos.org" target="_blank" rel="noreferrer">webKnossos</a> works too. Multichannel datasets use a <code>c</code> axis</li><li><strong>Supported dtypes:</strong> <code>uint8</code>, <code>uint16</code>, <code>int16</code>, <code>float32</code> (<code>float64</code> is read as <code>float32</code>). Other types, such as <code>int8</code> or <code>uint32</code>, are rejected with an explanation</li><li>Multiple resolution levels (datasets within <code>multiscales</code>) are used as LODs. Kiln reads each level&#39;s own size and per-axis downsampling (1× or 2×). If the stored levels don&#39;t fit that model, for example a coarse level a few slices short of half its parent, it falls back to a uniform 2:1 model and logs why. Force either model with <code>?pyramid=native</code> or <code>?pyramid=legacy</code></li><li>Voxel spacing is read from <code>coordinateTransformations</code> if present</li><li>OMERO metadata is used for per-channel window auto-leveling when available</li></ul><blockquote><p><strong>Note:</strong> Currently unsupported: more than 4 channels, and data types other than the ones listed above. <code>uint8</code> is stored as <code>r8unorm</code>; every other type is stored as <code>r16float</code> (half precision; WebGPU filterable-float32 is not universally available), which is not bit-exact across a full 16-bit range. <code>uint16</code> is normalised by its type range. <code>int16</code> and floats keep their raw values and are normalised in the shader by a data range: the OMERO window&#39;s min/max when present, otherwise the 0.1–99.9th percentile of the coarsest level.</p></blockquote><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>Pass the <code>.ome.zarr</code> URL directly to <code>KilnViewer.create()</code>:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { KilnViewer } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;kiln-render&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> viewer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KilnViewer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(canvas, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;https://example.com/data/scan.ome.zarr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Any URL that doesn&#39;t serve Kiln&#39;s sharded format (a <code>volume.json</code>) is read as OME-Zarr, so URLs without <code>.zarr</code>, such as webKnossos layers, work as well. Brick assembly (fetching Zarr chunks, decompressing, and re-chunking into 66³ bricks with ghost borders) runs in a Web Worker pool off the main thread. For Zarr v2 stores (NGFF 0.4) the metadata is read in two round trips and shared with the workers, so they start without touching the network.</p><h3 id="layout-tips-for-fast-streaming" tabindex="-1">Layout tips for fast streaming <a class="header-anchor" href="#layout-tips-for-fast-streaming" aria-label="Permalink to &quot;Layout tips for fast streaming&quot;">​</a></h3><p>Kiln streams whatever layout it is given, but two properties of the source decide how quickly a full coarse image can appear:</p><ul><li><strong>A pyramid that downsamples every axis.</strong> If the multiscale levels halve X and Y but keep Z at full resolution, the coarsest level can still be hundreds of megabytes (a 1920×1920×752 stack with four channels has a 240×240×752 coarsest level of about 270 MB compressed). Kiln shows the first bricks and the first channel early, but the complete base still costs that download. Add a level or two that also halve Z.</li><li><strong>Chunks that are not whole planes.</strong> With chunks of one full XY plane, every brick needs all planes of its Z range before it can be assembled, so nothing shows until most of a level has arrived. Cubic or near-cubic chunks (for example 64³ or 128³) let bricks stream independently.</li></ul><h2 id="public-ome-zarr-datasets" tabindex="-1">Public OME-Zarr datasets <a class="header-anchor" href="#public-ome-zarr-datasets" aria-label="Permalink to &quot;Public OME-Zarr datasets&quot;">​</a></h2><p>The <a href="https://registry.opendata.aws/ome-zarr-open-scivis/" target="_blank" rel="noreferrer">OME-Zarr Open SciVis Datasets</a> on AWS provide ready-to-use test volumes:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> viewer</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KilnViewer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  canvas,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;https://ome-zarr-scivis.s3.us-east-1.amazonaws.com/v0.5/96x2/beechnut.ome.zarr&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="axis-convention" tabindex="-1">Axis convention <a class="header-anchor" href="#axis-convention" aria-label="Permalink to &quot;Axis convention&quot;">​</a></h2><p>Most OME-Zarr stores dimensions as <code>[z, y, x]</code>; webKnossos writes <code>[x, y, z]</code>. Kiln reads the order from the <code>axes</code> metadata and uses <code>[x, y, z]</code> internally. Chunks are read through their strides, so no data is transposed.</p>`,20)])])}const u=a(r,[["render",o]]);export{k as __pageData,u as default};
